-- Operator-only read-only checkpoint. Active unrevoked session rows are excluded.
SELECT jsonb_build_object('capturedAt',clock_timestamp(),'postgresVersion',current_setting('server_version'),'schemaVersion',CASE WHEN strpos(pg_get_functiondef(to_regprocedure('musitu.resume_ai_assistance(text,uuid,boolean)')),'MUSITU_OWNER_AI_RESUMPTION_V17')>0 THEN 17 WHEN strpos(pg_get_functiondef('musitu.complete_development_reply(text,uuid,text,text,integer)'::regprocedure),'MUSITU_META_MESSAGE_ID_COMPATIBILITY_V16')>0 THEN 16 ELSE 15 END,'source',jsonb_build_object('project','jolly-scene-02112141','branch','br-jolly-fire-b4klddds','database',current_database()),'excludedActiveSessionRows',(SELECT count(*) FROM musitu_identity.sessions WHERE NOT revoked AND expires_at>CURRENT_TIMESTAMP),'data',jsonb_build_object('musitu.action_audit',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM musitu.action_audit t),'musitu.ai_policy',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM musitu.ai_policy t),'musitu.ai_requests',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM musitu.ai_requests t),'musitu.bookings',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM musitu.bookings t),'musitu.business_configuration',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM musitu.business_configuration t),'musitu.channel_consent_evidence',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM musitu.channel_consent_evidence t),'musitu.contacts',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM musitu.contacts t),'musitu.conversations',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM musitu.conversations t),'musitu.customer_suppressions',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM musitu.customer_suppressions t),'musitu.draft_approvals',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM musitu.draft_approvals t),'musitu.faqs',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM musitu.faqs t),'musitu.inbound_events',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM musitu.inbound_events t),'musitu.memberships',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM musitu.memberships t),'musitu.message_status_events',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM musitu.message_status_events t),'musitu.messages',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM musitu.messages t),'musitu.outbound_attempts',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM musitu.outbound_attempts t),'musitu.outbound_preparations',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM musitu.outbound_preparations t),'musitu.reply_drafts',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM musitu.reply_drafts t),'musitu.resources',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM musitu.resources t),'musitu.tenants',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM musitu.tenants t),'musitu.whatsapp_channels',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM musitu.whatsapp_channels t),'musitu_identity.sessions',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM musitu_identity.sessions t WHERE t.revoked OR t.expires_at<=CURRENT_TIMESTAMP)),'catalog',jsonb_build_array((SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) FROM (SELECT n.nspname,c.relname,pg_get_userbyid(c.relowner) AS owner,c.relrowsecurity,c.relforcerowsecurity,coalesce((SELECT jsonb_agg(a::text ORDER BY a::text) FROM unnest(c.relacl) a),'[]'::jsonb) AS acl FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('musitu','musitu_identity') AND c.relkind='r' ORDER BY 1,2) x),(SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) FROM (SELECT n.nspname,c.relname,a.attname,a.attnum,format_type(a.atttypid,a.atttypmod) AS type,a.attnotnull,pg_get_expr(d.adbin,d.adrelid) AS default_value,a.attidentity,a.attgenerated,coalesce((SELECT jsonb_agg(x::text ORDER BY x::text) FROM unnest(a.attacl) x),'[]'::jsonb) AS acl FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE n.nspname IN ('musitu','musitu_identity') AND c.relkind='r' AND a.attnum>0 AND NOT a.attisdropped ORDER BY 1,2,4) x),(SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) FROM (SELECT n.nspname,c.relname,k.conname,pg_get_constraintdef(k.oid) AS definition FROM pg_constraint k JOIN pg_class c ON c.oid=k.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('musitu','musitu_identity') ORDER BY 1,2,3) x),(SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) FROM (SELECT schemaname,tablename,policyname,permissive,roles,cmd,qual,with_check FROM pg_policies WHERE schemaname IN ('musitu','musitu_identity') ORDER BY 1,2,3) x),(SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) FROM (SELECT n.nspname,p.proname,pg_get_function_identity_arguments(p.oid) AS arguments,pg_get_userbyid(p.proowner) AS owner,coalesce((SELECT jsonb_agg(a::text ORDER BY a::text) FROM unnest(p.proacl) a),'[]'::jsonb) AS acl,pg_get_functiondef(p.oid) AS definition FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN ('musitu','musitu_identity') ORDER BY 1,2,3) x),(SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) FROM (SELECT nspname,pg_get_userbyid(nspowner) AS owner,coalesce((SELECT jsonb_agg(a::text ORDER BY a::text) FROM unnest(nspacl) a),'[]'::jsonb) AS acl FROM pg_namespace WHERE nspname IN ('musitu','musitu_identity') ORDER BY 1) x)),'dependencies',(SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) FROM (SELECT conrelid::regclass::text AS child,confrelid::regclass::text AS parent FROM pg_constraint WHERE contype='f' AND connamespace='musitu'::regnamespace ORDER BY 1,2) x),'roles',(SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) FROM (SELECT rolname,rolsuper,rolinherit,rolcreaterole,rolcreatedb,rolcanlogin,rolreplication,rolbypassrls FROM pg_roles WHERE rolname IN ('musitu_whatsapp_phase1_owner','musitu_runtime','musitu_ingress','musitu_commands') ORDER BY 1) x),'relationInventory',(SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) FROM (SELECT n.nspname||'.'||c.relname AS name FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('musitu','musitu_identity') AND c.relkind='r' ORDER BY 1) x)) AS checkpoint;
